import type { WizardData } from "@/lib/store/wizard-store";

/**
 * Generates a complete Supabase setup SQL script from wizard data.
 *
 * The SQL is split into sections, each generated by a dedicated function.
 * Feature toggles (features.onlineOrdering / reservations / gallery)
 * conditionally include or exclude their tables, RLS policies and seed data.
 *
 * Every section is a copy of a proven, working schema — no inline
 * subqueries inside RLS policies (that would cause infinite recursion),
 * always uses the is_admin() helper function.
 */
export function generateSQL(data: WizardData): string {
  const { features, brand } = data;

  const sections: string[] = [];

  sections.push(header(brand.name));
  sections.push(extensions());
  sections.push(enums());
  if (features.onlineOrdering) sections.push(sequence());

  sections.push(profilesTable());
  sections.push(siteSettingsTable());
  sections.push(contactMessagesTable());
  sections.push(menuTables());

  if (features.onlineOrdering) sections.push(ordersTables());
  if (features.reservations) sections.push(reservationsTable());
  if (features.gallery) sections.push(galleryTable());

  sections.push(indexesAndConstraints(data));
  sections.push(helperFunctions());
  sections.push(triggers());
  sections.push(rlsPolicies(features));
  if (features.gallery) sections.push(storageSetup());

  sections.push(seedData(data));
  sections.push(adminUser(data));

  return sections.join("\n\n");
}

// =====================================================================
// HEADER
// =====================================================================

function header(name: string) {
  return `-- =====================================================================
-- Restaurant Website Database Setup
-- Generated for: ${name || "Your Restaurant"}
-- Generated at: ${new Date().toISOString()}
-- =====================================================================
--
-- HOW TO USE:
-- 1. Copy this entire file.
-- 2. Go to your Supabase project → SQL Editor → New query.
-- 3. Paste and click RUN.
-- 4. If Supabase shows "Potential issues detected", choose
--    "Run without RLS" — this file defines its own RLS policies.
-- 5. Wait for the "Success. No rows returned" message.
--
-- This script is idempotent — safe to run multiple times.
-- =====================================================================`;
}

// =====================================================================
// EXTENSIONS
// =====================================================================

function extensions() {
  return `-- Extensions
create extension if not exists "pgcrypto";`;
}

// =====================================================================
// ENUMS (postgres types)
// =====================================================================

function enums() {
  return `-- =====================================================================
-- ENUM TYPES
-- =====================================================================

do $$ begin
  create type public.order_type as enum ('pickup', 'delivery', 'dine-in');
exception when duplicate_object then null; end $$;

do $$ begin
  create type public.order_status as enum ('pending', 'confirmed', 'preparing', 'ready', 'out-for-delivery', 'completed', 'cancelled');
exception when duplicate_object then null; end $$;

do $$ begin
  create type public.payment_method as enum ('jazzcash', 'easypaisa', 'cod');
exception when duplicate_object then null; end $$;

do $$ begin
  create type public.payment_status as enum ('unpaid', 'paid', 'failed', 'refunded');
exception when duplicate_object then null; end $$;

do $$ begin
  create type public.reservation_status as enum ('pending', 'confirmed', 'seated', 'cancelled', 'no-show');
exception when duplicate_object then null; end $$;`;
}

// =====================================================================
// SEQUENCE (for order numbers)
// =====================================================================

function sequence() {
  return `-- Sequence for generating order numbers
create sequence if not exists public.order_number_seq start 1;`;
}

function profilesTable(): string {
  return `-- =====================================================================
-- TABLE: profiles (linked to auth.users)
-- =====================================================================
create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  email text not null,
  full_name text,
  role text not null default 'admin',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create unique index if not exists profiles_email_key on public.profiles (email);`;
}

function siteSettingsTable(): string {
  return `-- =====================================================================
-- TABLE: site_settings (key-value store for admin-editable settings)
-- =====================================================================
create table if not exists public.site_settings (
  key text primary key,
  value jsonb not null,
  updated_at timestamptz not null default now()
);`;
}

function contactMessagesTable(): string {
  return `-- =====================================================================
-- TABLE: contact_messages
-- =====================================================================
create table if not exists public.contact_messages (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  email text not null,
  phone text,
  subject text,
  message text not null,
  is_read boolean not null default false,
  created_at timestamptz not null default now()
);`;
}

function menuTables(): string {
  return `-- =====================================================================
-- TABLE: menu_categories
-- =====================================================================
create table if not exists public.menu_categories (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  description text,
  sort_order integer not null default 0,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- =====================================================================
-- TABLE: menu_items
-- =====================================================================
create table if not exists public.menu_items (
  id uuid primary key default gen_random_uuid(),
  category_id uuid not null references public.menu_categories(id) on delete cascade,
  name text not null,
  description text,
  price numeric not null,
  image_url text,
  is_available boolean not null default true,
  is_featured boolean not null default false,
  tags text[] default '{}',
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);`;
}

function ordersTables(): string {
  return `-- =====================================================================
-- TABLE: orders
-- =====================================================================
create table if not exists public.orders (
  id uuid primary key default gen_random_uuid(),
  order_number text not null,
  customer_name text not null,
  customer_phone text not null,
  customer_email text,
  type public.order_type not null default 'pickup',
  status public.order_status not null default 'pending',
  payment_method public.payment_method not null default 'cod',
  payment_status public.payment_status not null default 'unpaid',
  payment_reference text,
  subtotal numeric not null default 0,
  delivery_fee numeric not null default 0,
  total numeric not null default 0,
  delivery_address text,
  notes text,
  customer_marked_paid_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create unique index if not exists orders_order_number_key on public.orders (order_number);

-- =====================================================================
-- TABLE: order_items
-- =====================================================================
create table if not exists public.order_items (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders(id) on delete cascade,
  menu_item_id uuid references public.menu_items(id) on delete set null,
  item_name text not null,
  unit_price numeric not null,
  quantity integer not null,
  line_total numeric not null,
  created_at timestamptz not null default now()
);`;
}

function reservationsTable(): string {
  return `-- =====================================================================
-- TABLE: reservations
-- =====================================================================
create table if not exists public.reservations (
  id uuid primary key default gen_random_uuid(),
  customer_name text not null,
  customer_phone text not null,
  customer_email text,
  party_size integer not null,
  reservation_date date not null,
  reservation_time time not null,
  status public.reservation_status not null default 'pending',
  special_requests text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);`;
}

function galleryTable(): string {
  return `-- =====================================================================
-- TABLE: gallery
-- =====================================================================
create table if not exists public.gallery (
  id uuid primary key default gen_random_uuid(),
  title text,
  description text,
  image_url text not null,
  sort_order integer not null default 0,
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);`;
}

function indexesAndConstraints(data: WizardData): string {
  const lines: string[] = [];
  lines.push(`-- =====================================================================
-- INDEXES
-- =====================================================================`);

  // Menu indexes (always)
  lines.push(`create index if not exists idx_menu_items_category on public.menu_items (category_id);
create index if not exists idx_menu_items_available on public.menu_items (is_available);
create index if not exists idx_menu_items_featured on public.menu_items (is_featured) where is_featured = true;`);

  // Contact
  lines.push(`create index if not exists idx_contact_messages_unread on public.contact_messages (is_read, created_at desc);`);

  // Orders (conditional)
  if (data.features.onlineOrdering) {
    lines.push(`create index if not exists idx_orders_created on public.orders (created_at desc);
create index if not exists idx_orders_status on public.orders (status);
create index if not exists idx_orders_customer_paid on public.orders (customer_marked_paid_at) where customer_marked_paid_at is not null;
create index if not exists idx_order_items_order on public.order_items (order_id);`);
  }

  // Reservations (conditional)
  if (data.features.reservations) {
    lines.push(`create index if not exists idx_reservations_date on public.reservations (reservation_date, reservation_time);
create index if not exists idx_reservations_status on public.reservations (status);`);
  }

  return lines.join("\n");
}

function helperFunctions(): string {
  return `-- =====================================================================
-- HELPER FUNCTIONS
-- =====================================================================

-- is_admin(): SECURITY DEFINER so it can read profiles without
-- triggering recursive RLS checks.
create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.profiles
    where id = auth.uid() and role = 'admin'
  );
$$;

-- handle_new_user(): auto-creates a profile row when a new user
-- is created in auth.users.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (id, email, full_name)
  values (
    new.id,
    new.email,
    coalesce(new.raw_user_meta_data->>'full_name', '')
  )
  on conflict (id) do nothing;
  return new;
end;
$$;

-- generate_order_number(): produces ORD-YYYYMMDD-0001 style numbers.
create or replace function public.generate_order_number()
returns text
language plpgsql
as $$
declare
  today text := to_char(now(), 'YYYYMMDD');
  next_val int;
begin
  select nextval('public.order_number_seq') into next_val;
  return 'ORD-' || today || '-' || lpad(next_val::text, 4, '0');
end;
$$;

-- set_order_number(): BEFORE INSERT trigger that fills order_number
-- when the application doesn't supply one.
create or replace function public.set_order_number()
returns trigger
language plpgsql
as $$
begin
  if new.order_number is null or new.order_number = '' then
    new.order_number := public.generate_order_number();
  end if;
  return new;
end;
$$;`;
}

function triggers(): string {
  return `-- =====================================================================
-- TRIGGERS
-- =====================================================================

-- Auto-create profile for every new signup
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- Auto-generate order_number on insert
drop trigger if exists trg_set_order_number on public.orders;
create trigger trg_set_order_number
  before insert on public.orders
  for each row execute function public.set_order_number();`;
}

function rlsPolicies(features: WizardData["features"]): string {
  const lines: string[] = [];

  lines.push(`-- =====================================================================
-- ROW LEVEL SECURITY
-- =====================================================================
-- Public reads, admin writes. All admin checks use is_admin() to
-- avoid recursive RLS evaluation.`);

  // Enable RLS on all core tables
  const tables = ["profiles", "site_settings", "contact_messages", "menu_categories", "menu_items"];
  if (features.onlineOrdering) tables.push("orders", "order_items");
  if (features.reservations) tables.push("reservations");
  if (features.gallery) tables.push("gallery");

  for (const t of tables) {
    lines.push(`alter table public.${t} enable row level security;`);
  }

  // Profiles
  lines.push(`drop policy if exists "profiles_self_read" on public.profiles;
create policy "profiles_self_read" on public.profiles
  for select to authenticated
  using ((auth.uid() = id) or public.is_admin());

drop policy if exists "profiles_self_update" on public.profiles;
create policy "profiles_self_update" on public.profiles
  for update to authenticated
  using (auth.uid() = id)
  with check (auth.uid() = id);`);

  // site_settings
  lines.push(`drop policy if exists "site_settings_public_read" on public.site_settings;
create policy "site_settings_public_read" on public.site_settings
  for select using (true);

drop policy if exists "site_settings_admin_all" on public.site_settings;
create policy "site_settings_admin_all" on public.site_settings
  for all to authenticated
  using (public.is_admin())
  with check (public.is_admin());`);

  // contact_messages
  lines.push(`drop policy if exists "contact_messages_public_insert" on public.contact_messages;
create policy "contact_messages_public_insert" on public.contact_messages
  for insert with check (true);

drop policy if exists "contact_messages_admin_read" on public.contact_messages;
create policy "contact_messages_admin_read" on public.contact_messages
  for select to authenticated using (public.is_admin());

drop policy if exists "contact_messages_admin_update" on public.contact_messages;
create policy "contact_messages_admin_update" on public.contact_messages
  for update to authenticated using (public.is_admin());`);

  // menu_categories
  lines.push(`drop policy if exists "menu_categories_public_read" on public.menu_categories;
create policy "menu_categories_public_read" on public.menu_categories
  for select using ((is_active = true) or public.is_admin());

drop policy if exists "menu_categories_admin_all" on public.menu_categories;
create policy "menu_categories_admin_all" on public.menu_categories
  for all to authenticated
  using (public.is_admin())
  with check (public.is_admin());`);

  // menu_items
  lines.push(`drop policy if exists "menu_items_public_read" on public.menu_items;
create policy "menu_items_public_read" on public.menu_items
  for select using ((is_available = true) or public.is_admin());

drop policy if exists "menu_items_admin_all" on public.menu_items;
create policy "menu_items_admin_all" on public.menu_items
  for all to authenticated
  using (public.is_admin())
  with check (public.is_admin());`);

  // orders + order_items (conditional)
  if (features.onlineOrdering) {
    lines.push(`drop policy if exists "orders_public_insert" on public.orders;
create policy "orders_public_insert" on public.orders
  for insert with check (true);

drop policy if exists "orders_admin_read" on public.orders;
create policy "orders_admin_read" on public.orders
  for select to authenticated using (public.is_admin());

drop policy if exists "orders_admin_update" on public.orders;
create policy "orders_admin_update" on public.orders
  for update to authenticated using (public.is_admin());

drop policy if exists "order_items_public_insert" on public.order_items;
create policy "order_items_public_insert" on public.order_items
  for insert with check (true);

drop policy if exists "order_items_admin_read" on public.order_items;
create policy "order_items_admin_read" on public.order_items
  for select to authenticated using (public.is_admin());`);
  }

  // reservations (conditional)
  if (features.reservations) {
    lines.push(`drop policy if exists "reservations_public_insert" on public.reservations;
create policy "reservations_public_insert" on public.reservations
  for insert with check (true);

drop policy if exists "reservations_admin_read" on public.reservations;
create policy "reservations_admin_read" on public.reservations
  for select to authenticated using (public.is_admin());

drop policy if exists "reservations_admin_update" on public.reservations;
create policy "reservations_admin_update" on public.reservations
  for update to authenticated using (public.is_admin());`);
  }

  // gallery (conditional)
  if (features.gallery) {
    lines.push(`drop policy if exists "gallery_public_read" on public.gallery;
create policy "gallery_public_read" on public.gallery
  for select using ((is_active = true) or public.is_admin());

drop policy if exists "gallery_admin_all" on public.gallery;
create policy "gallery_admin_all" on public.gallery
  for all to authenticated
  using (public.is_admin())
  with check (public.is_admin());`);
  }

  return lines.join("\n");
}

function storageSetup(): string {
  return `-- =====================================================================
-- STORAGE BUCKET + POLICIES (for gallery + menu images)
-- =====================================================================

insert into storage.buckets (id, name, public)
values ('gallery', 'gallery', true)
on conflict (id) do nothing;

drop policy if exists "gallery_public_read" on storage.objects;
create policy "gallery_public_read" on storage.objects
  for select using (bucket_id = 'gallery');

drop policy if exists "gallery_admin_insert" on storage.objects;
create policy "gallery_admin_insert" on storage.objects
  for insert to authenticated
  with check (bucket_id = 'gallery' and public.is_admin());

drop policy if exists "gallery_admin_update" on storage.objects;
create policy "gallery_admin_update" on storage.objects
  for update to authenticated
  using (bucket_id = 'gallery' and public.is_admin());

drop policy if exists "gallery_admin_delete" on storage.objects;
create policy "gallery_admin_delete" on storage.objects
  for delete to authenticated
  using (bucket_id = 'gallery' and public.is_admin());`;
}

function seedData(data: WizardData): string {
  const { brand, contact, hours, currency, paymentAccounts, whatsapp, features } = data;

  function esc(s: string) {
    return s.replace(/'/g, "''");
  }

  const brandJson = JSON.stringify({
    name: brand.name,
    tagline: brand.tagline,
    heroPunchline: brand.heroPunchline,
  }).replace(/'/g, "''");

  const contactJson = JSON.stringify({
    phone: contact.phone,
    email: contact.email,
    address: contact.address,
  }).replace(/'/g, "''");

  const hoursJson = JSON.stringify(hours).replace(/'/g, "''");

  const paymentsJson = JSON.stringify(paymentAccounts).replace(/'/g, "''");
  const whatsappJson = JSON.stringify(whatsapp).replace(/'/g, "''");

  const lines: string[] = [];
  lines.push(`-- =====================================================================
-- SEED DATA (default settings — admin can edit these later)
-- =====================================================================`);

  lines.push(`insert into public.site_settings (key, value) values
  ('brand', '${brandJson}'::jsonb),
  ('contact', '${contactJson}'::jsonb),
  ('hours', '${hoursJson}'::jsonb),
  ('currency', '"${esc(currency)}"'::jsonb),
  ('paymentAccounts', '${paymentsJson}'::jsonb),
  ('whatsapp', '${whatsappJson}'::jsonb)
on conflict (key) do nothing;`);

  // Default menu categories + a few items
  lines.push(`-- Default menu categories
insert into public.menu_categories (name, description, sort_order) values
  ('Starters', 'Appetizers and small plates', 1),
  ('Main Course', 'Signature mains', 2),
  ('Desserts', 'Sweet finishes', 3),
  ('Beverages', 'Hot and cold drinks', 4)
on conflict do nothing;`);

  // Sample menu items
  lines.push(`-- Sample menu items (admin can edit/delete from admin panel)
do $$
declare
  v_starters uuid;
  v_mains uuid;
  v_desserts uuid;
  v_drinks uuid;
begin
  select id into v_starters from public.menu_categories where name = 'Starters' limit 1;
  select id into v_mains from public.menu_categories where name = 'Main Course' limit 1;
  select id into v_desserts from public.menu_categories where name = 'Desserts' limit 1;
  select id into v_drinks from public.menu_categories where name = 'Beverages' limit 1;

  if v_starters is not null then
    insert into public.menu_items (category_id, name, description, price, is_featured, sort_order) values
      (v_starters, 'Garlic Bread', 'Toasted bread with garlic butter and herbs', 350, false, 1),
      (v_starters, 'Chicken Wings', 'Spicy grilled wings with dip', 650, true, 2);
  end if;

  if v_mains is not null then
    insert into public.menu_items (category_id, name, description, price, is_featured, sort_order) values
      (v_mains, 'Chicken Karahi', 'Traditional Pakistani chicken karahi', 1500, true, 1),
      (v_mains, 'Beef Burger', 'Juicy beef patty with cheese and fries', 950, true, 2),
      (v_mains, 'Biryani', 'Aromatic basmati rice with chicken', 800, true, 3);
  end if;

  if v_desserts is not null then
    insert into public.menu_items (category_id, name, description, price, is_featured, sort_order) values
      (v_desserts, 'Chocolate Cake', 'Rich chocolate layer cake', 450, false, 1);
  end if;

  if v_drinks is not null then
    insert into public.menu_items (category_id, name, description, price, is_featured, sort_order) values
      (v_drinks, 'Fresh Lime', 'Freshly squeezed lime juice', 250, false, 1),
      (v_drinks, 'Soft Drink', 'Chilled canned soft drink', 150, false, 2);
  end if;
end $$;`);

  return lines.join("\n");
}

function adminUser(data: WizardData): string {
  const email = data.supabase.adminEmail || "admin@example.com";
  const password = data.supabase.adminPassword || "changeme123";
  const name = data.brand.name || "Admin";
  const fullName = name + " Admin";

  function esc(s: string) {
    return s.replace(/'/g, "''");
  }

  return `-- =====================================================================
-- ADMIN USER (auto-created)
-- =====================================================================
-- Login with: ${email}
-- Password:   ${password}
-- Change the password after first login!
-- =====================================================================

do $$
declare
  v_user_id uuid;
begin
  -- Check if user already exists
  select id into v_user_id from auth.users where email = '${esc(email)}';

  if v_user_id is null then
    v_user_id := gen_random_uuid();

    insert into auth.users (
      instance_id, id, aud, role, email,
      encrypted_password,
      email_confirmed_at,
      raw_app_meta_data, raw_user_meta_data,
      created_at, updated_at,
      confirmation_token, recovery_token,
      email_change, email_change_token_new
    ) values (
      '00000000-0000-0000-0000-000000000000',
      v_user_id,
      'authenticated',
      'authenticated',
      '${esc(email)}',
      crypt('${esc(password)}', gen_salt('bf')),
      now(),
      '{"provider":"email","providers":["email"]}'::jsonb,
      '{"email_verified":true,"full_name":"${esc(fullName)}"}'::jsonb,
      now(), now(),
      '', '', '', ''
    );

    -- identity row (required for password login)
    insert into auth.identities (
      id, user_id, identity_data, provider, provider_id,
      last_sign_in_at, created_at, updated_at
    ) values (
      gen_random_uuid(),
      v_user_id,
      jsonb_build_object(
        'sub', v_user_id::text,
        'email', '${esc(email)}',
        'email_verified', true,
        'phone_verified', false
      ),
      'email',
      '${esc(email)}',
      now(), now(), now()
    );
  end if;

  -- Ensure profile row has admin role
  insert into public.profiles (id, email, full_name, role)
  values (v_user_id, '${esc(email)}', '${esc(fullName)}', 'admin')
  on conflict (id) do update set role = 'admin';
end $$;`;
}
